-- MaaPushti demo data: 5 Maa Bondhus, 5 gynecologists, 7 shopkeepers, 25 mothers.
-- Every demo login uses the password demo1234. Run once in Supabase > SQL Editor; running again replaces the demo data.
-- Phone numbers are made up. Before a live demo, change a mother's number to a teammate's phone if you want to call her.

-- Make sure the profile columns from update 2 exist.
alter table public.profiles add column if not exists division text, add column if not exists district text, add column if not exists upazila text,
  add column if not exists union_name text, add column if not exists contact_phone text, add column if not exists alt_phone text, add column if not exists photo text;

